-- 285: 指導計画テンプレ初期seed(月案/週案/個人案・記入ヒント+例文入り)。284の基盤に投入。
-- sections jsonb: [{key,label,hint,fields:[{key,label,required,subject,hint,examples[]}]}]。全て version=1・未公開(下書き)。
-- 管理者が内容確認後に公開する運用。年間/全体/安全/1・2歳月案の細分は後続seedで追加。

insert into guidance_plan_templates (plan_type, age_variant, version, title, sections, is_published)
values ('monthly', 'age0', 1, '月案(0歳児)', '[{"key": "aim", "label": "ねらい", "hint": "その月/週に育てたい姿を、子どもを主語に『〜を楽しむ』『〜しようとする』の形で。理想論より現実的に。", "fields": [{"key": "aim", "label": "ねらい", "required": true, "subject": "子ども", "examples": ["夏ならではの遊びを通して、水や感触に親しむ。", "身近な友達と関わりながら、好きな遊びを楽しむ。"]}]}, {"key": "nursing", "label": "養護", "hint": "保育者を主語に。健康・安全・清潔(生命の保持)と、安心・信頼(情緒の安定)を書きます。", "fields": [{"key": "nursing", "label": "養護", "required": true, "subject": "保育者", "examples": ["一人ひとりの健康状態を把握し、快適に過ごせるようにする。", "スキンシップや優しい言葉かけで安心感を持てるようにする。"]}]}, {"key": "childcare_support", "label": "子育て支援", "fields": [{"key": "$子育て支援$", "label": "子育て支援", "required": false, "subject": "保育者"}]}, {"key": "consideration", "label": "保育の実施に関わる配慮事項", "fields": [{"key": "$保育の実施に関わる配慮事項$", "label": "配慮事項", "required": false, "subject": "保育者"}]}, {"key": "healthygrow", "label": "健やかに伸び伸びと育つ", "hint": "心身の健康・生活リズム(食事/睡眠/排泄)や、寝返り・はいはい・つかまり立ちなど体を動かす育ちを、子どもを主語に前向きに書きます。", "fields": [{"key": "healthygrow*aim", "label": "ねらい", "required": true, "subject": "子ども", "examples": ["保育者に見守られ、安心してよく食べ、よく眠る。", "寝返りやはいはいなど、体を動かす心地よさを味わう。", "つかまり立ちや伝い歩きを楽しむ。"]}, {"key": "healthygrow*content", "label": "内容", "required": true, "subject": "子ども", "examples": ["一人ひとりの生活リズムに合わせて授乳・睡眠・排泄を行う。", "広いスペースで安全に体を動かして遊ぶ。"]}, {"key": "healthygrow*$内容の取り扱い$", "label": "内容の取り扱い", "required": true, "subject": "保育者", "examples": ["一人ひとりの発達に合わせて援助し、心地よく過ごせるようにする。", "動きやすいよう環境を整え、危険のないよう見守る。"]}]}, {"key": "withfeelings", "label": "身近な人と気持ちが通じ合う", "hint": "特定の保育者との信頼関係、喃語・表情・身振りでのやりとり、人への興味を、子どもを主語に書きます。", "fields": [{"key": "withfeelings*aim", "label": "ねらい", "required": true, "subject": "子ども", "examples": ["特定の保育者に親しみ、安心して過ごす。", "喃語や表情、身振りで気持ちを伝えようとする。", "保育者とのやりとりを喜ぶ。"]}, {"key": "withfeelings*content", "label": "内容", "required": true, "subject": "子ども", "examples": ["応答的に関わり、子どもの発信を受け止める。", "わらべうたや触れ合い遊びを楽しむ。"]}, {"key": "withfeelings*$内容の取り扱い$", "label": "内容の取り扱い", "required": true, "subject": "保育者", "examples": ["子どもの気持ちを受け止め、優しく言葉をかけて安心感を持てるようにする。"]}]}, {"key": "sensitivity", "label": "身近なものと関わり感性が育つ", "hint": "身近な玩具・自然物・音・光への興味や、見る・触れる・聴くといった感覚の育ちを、子どもを主語に書きます。", "fields": [{"key": "sensitivity*aim", "label": "ねらい", "required": true, "subject": "子ども", "examples": ["身近な玩具や自然物に触れ、感触や音を楽しむ。", "保育者と一緒に手遊びや歌を楽しむ。"]}, {"key": "sensitivity*content", "label": "内容", "required": true, "subject": "子ども", "examples": ["さまざまな素材や玩具に触れて遊ぶ。", "音の出る玩具や絵本に親しむ。"]}, {"key": "sensitivity*$内容の取り扱い$", "label": "内容の取り扱い", "required": true, "subject": "保育者", "examples": ["安全な玩具や素材を用意し、興味を持って関われるよう環境を整える。"]}]}, {"key": "health", "label": "健康", "hint": "生活習慣・運動・健康安全を、子どもを主語に。『〜しようとする』『〜を楽しむ』の形で。", "fields": [{"key": "health*aim", "label": "ねらい", "required": true, "subject": "子ども", "examples": ["保育者に見守られながら、体を十分に動かして遊ぶ。", "簡単な身の回りのことを自分でしようとする。"]}, {"key": "health*content", "label": "内容", "required": true, "subject": "子ども", "examples": ["戸外や室内で全身を使って遊ぶ。", "手洗いや着脱を保育者と一緒に行う。"]}, {"key": "health*$内容の取り扱い$", "label": "内容の取り扱い", "required": true, "subject": "保育者", "examples": ["一人ひとりのペースを尊重し、できた喜びを認めていく。"]}]}, {"key": "relations", "label": "人間関係", "hint": "友達や保育者との関わり、思いやり・きまりを、子どもを主語に。", "fields": [{"key": "relations*aim", "label": "ねらい", "required": true, "subject": "子ども", "examples": ["友達や保育者と関わって遊ぶことを楽しむ。", "順番を待つなど簡単な約束を守ろうとする。"]}, {"key": "relations*content", "label": "内容", "required": true, "subject": "子ども", "examples": ["ごっこ遊びや簡単なルールのある遊びを楽しむ。"]}, {"key": "relations*$内容の取り扱い$", "label": "内容の取り扱い", "required": true, "subject": "保育者", "examples": ["子ども同士の思いをつなぎ、関わりを見守り支える。"]}]}, {"key": "environment", "label": "環境", "hint": "身近な自然・物・季節への興味や探索を、子どもを主語に。", "fields": [{"key": "environment*aim", "label": "ねらい", "required": true, "subject": "子ども", "examples": ["身近な自然や物に興味を持ち、見たり触れたりして関わる。"]}, {"key": "environment*content", "label": "内容", "required": true, "subject": "子ども", "examples": ["季節の自然物に触れて遊ぶ。", "身の回りの物の仕組みに興味を持つ。"]}, {"key": "environment*$内容の取り扱い$", "label": "内容の取り扱い", "required": true, "subject": "保育者", "examples": ["興味を引き出す素材や場を用意し、探索を見守る。"]}]}, {"key": "lang", "label": "言葉", "hint": "言葉のやりとり・絵本・歌への親しみを、子どもを主語に。", "fields": [{"key": "lang*aim", "label": "ねらい", "required": true, "subject": "子ども", "examples": ["保育者や友達と言葉のやりとりを楽しむ。", "絵本や歌に親しみ、言葉の楽しさを感じる。"]}, {"key": "lang*content", "label": "内容", "required": true, "subject": "子ども", "examples": ["絵本の読み聞かせや言葉遊びを楽しむ。"]}, {"key": "lang*$内容の取り扱い$", "label": "内容の取り扱い", "required": true, "subject": "保育者", "examples": ["子どもの言葉を受け止め、丁寧に応答する。"]}]}, {"key": "expression", "label": "表現", "hint": "歌・リズム・造形・身体表現の楽しさを、子どもを主語に。", "fields": [{"key": "expression*aim", "label": "ねらい", "required": true, "subject": "子ども", "examples": ["歌や手遊び、体を動かす表現を楽しむ。", "描いたり作ったりして楽しむ。"]}, {"key": "expression*content", "label": "内容", "required": true, "subject": "子ども", "examples": ["季節の歌やリズム遊び、簡単な製作を楽しむ。"]}, {"key": "expression*$内容の取り扱い$", "label": "内容の取り扱い", "required": true, "subject": "保育者", "examples": ["自由な表現を認め、楽しむ気持ちを大切にする。"]}]}, {"key": "reflection", "label": "評価・反省", "hint": "月末に記入。次月の計画・AI生成のソースになります。", "fields": [{"key": "reflection", "label": "評価・反省", "required": false, "subject": "保育者"}]}]'::jsonb, false)
on conflict (plan_type, coalesce(age_variant,''), version) do nothing;

