insert into guidance_plan_templates (plan_type, age_variant, version, title, sections, is_published)
values ('weekly', 'age0', 1, '週案(0歳児)', '[{"key": "kidsstate", "label": "最近の子どもの姿", "hint": "連絡帳・園内記録・発達の様子から、その子の今の姿を具体的に(できるようになったこと・興味・生活面)。", "fields": [{"key": "kidsstate", "label": "最近の子どもの姿", "required": true, "subject": "子ども", "examples": ["つかまり立ちが安定し、伝い歩きを楽しむ姿が増えてきた。", "スプーンを使って自分で食べようとする。"]}]}, {"key": "aim", "label": "今週のねらい", "hint": "その月/週に育てたい姿を、子どもを主語に『〜を楽しむ』『〜しようとする』の形で。理想論より現実的に。", "fields": [{"key": "aim", "label": "今週のねらい", "required": true, "subject": "子ども", "examples": ["夏ならではの遊びを通して、水や感触に親しむ。", "身近な友達と関わりながら、好きな遊びを楽しむ。"]}]}, {"key": "healthygrow", "label": "健やかに伸び伸びと育つ", "hint": "心身の健康・生活リズム(食事/睡眠/排泄)や、寝返り・はいはい・つかまり立ちなど体を動かす育ちを、子どもを主語に前向きに書きます。", "fields": [{"key": "healthygrow*content", "label": "内容", "required": true, "subject": "子ども", "examples": ["一人ひとりの生活リズムに合わせて授乳・睡眠・排泄を行う。", "広いスペースで安全に体を動かして遊ぶ。"]}, {"key": "healthygrow*envicomp", "label": "環境構成", "required": true, "subject": "保育者"}, {"key": "healthygrow*expected", "label": "予想される子どもの姿", "required": true, "subject": "子ども"}, {"key": "healthygrow*aid", "label": "保育者の援助", "required": true, "subject": "保育者", "examples": ["一人ひとりの発達に合わせて援助し、心地よく過ごせるようにする。", "動きやすいよう環境を整え、危険のないよう見守る。"]}]}, {"key": "withfeelings", "label": "身近な人と気持ちが通じ合う", "hint": "特定の保育者との信頼関係、喃語・表情・身振りでのやりとり、人への興味を、子どもを主語に書きます。", "fields": [{"key": "withfeelings*content", "label": "内容", "required": true, "subject": "子ども", "examples": ["応答的に関わり、子どもの発信を受け止める。", "わらべうたや触れ合い遊びを楽しむ。"]}, {"key": "withfeelings*envicomp", "label": "環境構成", "required": true, "subject": "保育者"}, {"key": "withfeelings*expected", "label": "予想される子どもの姿", "required": true, "subject": "子ども"}, {"key": "withfeelings*aid", "label": "保育者の援助", "required": true, "subject": "保育者", "examples": ["子どもの気持ちを受け止め、優しく言葉をかけて安心感を持てるようにする。"]}]}, {"key": "sensitivity", "label": "身近なものと関わり感性が育つ", "hint": "身近な玩具・自然物・音・光への興味や、見る・触れる・聴くといった感覚の育ちを、子どもを主語に書きます。", "fields": [{"key": "sensitivity*content", "label": "内容", "required": true, "subject": "子ども", "examples": ["さまざまな素材や玩具に触れて遊ぶ。", "音の出る玩具や絵本に親しむ。"]}, {"key": "sensitivity*envicomp", "label": "環境構成", "required": true, "subject": "保育者"}, {"key": "sensitivity*expected", "label": "予想される子どもの姿", "required": true, "subject": "子ども"}, {"key": "sensitivity*aid", "label": "保育者の援助", "required": true, "subject": "保育者", "examples": ["安全な玩具や素材を用意し、興味を持って関われるよう環境を整える。"]}]}, {"key": "daily", "label": "日別(月〜土)", "hint": "休園日(日曜・祝日・年末年始)は入力不要。", "fields": [{"key": "aim*mon", "label": "月:ねらい", "required": false, "subject": "子ども"}, {"key": "content*mon", "label": "月:予想される内容", "required": false, "subject": "子ども"}, {"key": "aid*mon", "label": "月:保育者の援助", "required": false, "subject": "保育者"}, {"key": "envicomp*mon", "label": "月:環境構成", "required": false, "subject": "保育者"}, {"key": "aim*tue", "label": "火:ねらい", "required": false, "subject": "子ども"}, {"key": "content*tue", "label": "火:予想される内容", "required": false, "subject": "子ども"}, {"key": "aid*tue", "label": "火:保育者の援助", "required": false, "subject": "保育者"}, {"key": "envicomp*tue", "label": "火:環境構成", "required": false, "subject": "保育者"}, {"key": "aim*wed", "label": "水:ねらい", "required": false, "subject": "子ども"}, {"key": "content*wed", "label": "水:予想される内容", "required": false, "subject": "子ども"}, {"key": "aid*wed", "label": "水:保育者の援助", "required": false, "subject": "保育者"}, {"key": "envicomp*wed", "label": "水:環境構成", "required": false, "subject": "保育者"}, {"key": "aim*thu", "label": "木:ねらい", "required": false, "subject": "子ども"}, {"key": "content*thu", "label": "木:予想される内容", "required": false, "subject": "子ども"}, {"key": "aid*thu", "label": "木:保育者の援助", "required": false, "subject": "保育者"}, {"key": "envicomp*thu", "label": "木:環境構成", "required": false, "subject": "保育者"}, {"key": "aim*fri", "label": "金:ねらい", "required": false, "subject": "子ども"}, {"key": "content*fri", "label": "金:予想される内容", "required": false, "subject": "子ども"}, {"key": "aid*fri", "label": "金:保育者の援助", "required": false, "subject": "保育者"}, {"key": "envicomp*fri", "label": "金:環境構成", "required": false, "subject": "保育者"}, {"key": "aim*sat", "label": "土:ねらい", "required": false, "subject": "子ども"}, {"key": "content*sat", "label": "土:予想される内容", "required": false, "subject": "子ども"}, {"key": "aid*sat", "label": "土:保育者の援助", "required": false, "subject": "保育者"}, {"key": "envicomp*sat", "label": "土:環境構成", "required": false, "subject": "保育者"}]}, {"key": "reflection", "label": "評価・反省", "required": false, "fields": [{"key": "reflection", "label": "評価・反省", "required": false, "subject": "保育者"}]}]'::jsonb, false)
