insert into guidance_plan_templates (plan_type, age_variant, version, title, sections, is_published)
values ('weekly', 'age1plus', 1, '週案(1歳以上)', '[{"key": "kidsstate", "label": "最近の子どもの姿", "hint": "連絡帳・園内記録・発達の様子から、その子の今の姿を具体的に(できるようになったこと・興味・生活面)。", "fields": [{"key": "kidsstate", "label": "最近の子どもの姿", "required": true, "subject": "子ども", "examples": ["つかまり立ちが安定し、伝い歩きを楽しむ姿が増えてきた。", "スプーンを使って自分で食べようとする。"]}]}, {"key": "aim", "label": "今週のねらい", "hint": "その月/週に育てたい姿を、子どもを主語に『〜を楽しむ』『〜しようとする』の形で。理想論より現実的に。", "fields": [{"key": "aim", "label": "今週のねらい", "required": true, "subject": "子ども", "examples": ["夏ならではの遊びを通して、水や感触に親しむ。", "身近な友達と関わりながら、好きな遊びを楽しむ。"]}]}, {"key": "nursing", "label": "養護(生命の保持・情緒の安定)", "hint": "保育者を主語に。健康・安全・清潔(生命の保持)と、安心・信頼(情緒の安定)を書きます。", "fields": [{"key": "nursing*content", "label": "内容", "required": true, "subject": "子ども"}, {"key": "nursing*envicomp", "label": "環境構成", "required": true, "subject": "保育者"}, {"key": "nursing*expected", "label": "予想される子どもの姿", "required": true, "subject": "子ども"}, {"key": "nursing*aid", "label": "保育者の援助", "required": true, "subject": "保育者"}]}, {"key": "education", "label": "教育", "hint": "養護と並ぶ教育のねらい。年齢に応じ、子どもを主語に育ちを書きます。", "fields": [{"key": "education*content", "label": "内容", "required": true, "subject": "子ども"}, {"key": "education*envicomp", "label": "環境構成", "required": true, "subject": "保育者"}, {"key": "education*expected", "label": "予想される子どもの姿", "required": true, "subject": "子ども"}, {"key": "education*aid", "label": "保育者の援助", "required": true, "subject": "保育者"}]}, {"key": "daily", "label": "日別(月〜土)", "hint": "休園日(日曜・祝日・年末年始)は入力不要。", "fields": [{"key": "aim*mon", "label": "月:ねらい", "required": false, "subject": "子ども"}, {"key": "content*mon", "label": "月:予想される内容", "required": false, "subject": "子ども"}, {"key": "aid*mon", "label": "月:保育者の援助", "required": false, "subject": "保育者"}, {"key": "envicomp*mon", "label": "月:環境構成", "required": false, "subject": "保育者"}, {"key": "aim*tue", "label": "火:ねらい", "required": false, "subject": "子ども"}, {"key": "content*tue", "label": "火:予想される内容", "required": false, "subject": "子ども"}, {"key": "aid*tue", "label": "火:保育者の援助", "required": false, "subject": "保育者"}, {"key": "envicomp*tue", "label": "火:環境構成", "required": false, "subject": "保育者"}, {"key": "aim*wed", "label": "水:ねらい", "required": false, "subject": "子ども"}, {"key": "content*wed", "label": "水:予想される内容", "required": false, "subject": "子ども"}, {"key": "aid*wed", "label": "水:保育者の援助", "required": false, "subject": "保育者"}, {"key": "envicomp*wed", "label": "水:環境構成", "required": false, "subject": "保育者"}, {"key": "aim*thu", "label": "木:ねらい", "required": false, "subject": "子ども"}, {"key": "content*thu", "label": "木:予想される内容", "required": false, "subject": "子ども"}, {"key": "aid*thu", "label": "木:保育者の援助", "required": false, "subject": "保育者"}, {"key": "envicomp*thu", "label": "木:環境構成", "required": false, "subject": "保育者"}, {"key": "aim*fri", "label": "金:ねらい", "required": false, "subject": "子ども"}, {"key": "content*fri", "label": "金:予想される内容", "required": false, "subject": "子ども"}, {"key": "aid*fri", "label": "金:保育者の援助", "required": false, "subject": "保育者"}, {"key": "envicomp*fri", "label": "金:環境構成", "required": false, "subject": "保育者"}, {"key": "aim*sat", "label": "土:ねらい", "required": false, "subject": "子ども"}, {"key": "content*sat", "label": "土:予想される内容", "required": false, "subject": "子ども"}, {"key": "aid*sat", "label": "土:保育者の援助", "required": false, "subject": "保育者"}, {"key": "envicomp*sat", "label": "土:環境構成", "required": false, "subject": "保育者"}]}, {"key": "reflection", "label": "評価・反省", "fields": [{"key": "reflection", "label": "評価・反省", "required": false, "subject": "保育者"}]}]'::jsonb, false)
